import { getUnversionedNeonServer } from '../react-adapters/utils/react-utils';
export function loadNeonTheme(theme) {
    const existingThemeStyleTag = document.getElementById('neon-theme-style-link');
    if (existingThemeStyleTag == null) {
        if (theme !== 'default') {
            const themeStyleTag = document.createElement('link');
            themeStyleTag.setAttribute('rel', 'stylesheet');
            themeStyleTag.setAttribute('href', getUnversionedNeonServer() + '/themes/' + theme + '.css');
            themeStyleTag.id = 'neon-theme-style-link';
            document.head.appendChild(themeStyleTag);
        }
    }
    else {
        if (theme !== 'default') {
            existingThemeStyleTag.setAttribute('href', getUnversionedNeonServer() + '/themes/' + theme + '.css');
        }
        else {
            existingThemeStyleTag.remove();
        }
    }
}
